// 顺序不能漏字段或重复；新建内存记录允许暂未指定顺序。
bool order(const FieldOrder& value,const std::set<StableId>& fields){return value.empty()||(value.size()==fields.size()&&std::set<StableId>(value.begin(),value.end())==fields);}
bool id(const StableId& text){return !text.empty()&&text.size()<=256;}
// 来源与禀赋都经其自己的严格解码，外层不能用第一个同名键遮盖伪造数据。
BirthArrangementSource source(const V& v,Integer version){auto r=decode_birth_arrangement_source(v,version);if(!r.ok)boundary::fail(r.error.original.code,"birth/source");return std::move(r.value);}
// BirthProposal的局部形状不代替原Common事实序、真实人物及资源完整核验。
Status shape(const BirthProposal& p){std::set<StableId> fields{"kind","source"};return (p.kind=="family_birth_proposed")&&order(p.field_order,fields)?common_success():common_failure("InvalidBirthProposal");}
BirthProposal read_BirthProposal(const V& v,Integer version){using namespace boundary;fields(v,{"kind","source"},{},"family_birth");BirthProposal p;p.kind=get_string(v,"kind","");p.source=source(field(v,"source",""),version);p.field_order=boundary::order(v);auto valid=shape(p);if(!valid.ok)fail(valid.error.original.code,"");return p;}
V encode(const BirthProposal& p){return family_projection::encode([&](auto& w){return emit_birth_proposal_fields(w,p);});}
Status visit(CodecVisitor& c,BirthProposal& p,Integer version){c.field("kind",p.kind);c.object("source",[&](CodecVisitor& at){return visit_birth_arrangement_source(at,p.source,version);});common_checkpoint::strings(c,"field_order",p.field_order);if(!c.status().ok)return c.status();auto valid=shape(p);return valid.ok?c.status():c.reject(valid.error.original.code);}
// BirthReply的局部形状不代替原Common事实序、真实人物及资源完整核验。
