BirthReply read_BirthReply(const V& v,Integer version){using namespace boundary;fields(v,{"kind","proposal_id","actor_id","decision","tick","revision","reserved_food","due_tick"},{"confirmation"},"family_birth");BirthReply p;p.kind=get_string(v,"kind","");p.proposal_id=get_string(v,"proposal_id","");p.actor_id=get_string(v,"actor_id","");p.decision=get_string(v,"decision","");p.tick=get_int(v,"tick","");p.revision=get_int(v,"revision","");if(const auto* at=v.find("confirmation"))p.confirmation=source(*at,version);p.reserved_food=get_int(v,"reserved_food","");p.due_tick=get_int(v,"due_tick","");p.field_order=boundary::order(v);auto valid=shape(p);if(!valid.ok)fail(valid.error.original.code,"");return p;}
